create table eba_demo_dg_orders (
    order_id       number
        generated by default on null as identity
    not null enable,
    order_datetime timestamp(6) not null enable,
    customer_id    number not null enable,
    order_status   varchar2(10 byte) not null enable
);

alter table eba_demo_dg_orders
    add constraint eba_demo_dg_orders_pk primary key ( order_id )
        using index enable;

alter table eba_demo_dg_orders
    add constraint eba_demo_dg_ord_status_c
        check ( order_status in ( 'CANCELLED', 'COMPLETE', 'OPEN', 'PAID', 'REFUNDED',
                                  'SHIPPED' ) ) enable;


